package dev.matchlab;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;
class TelemetryToolsTest{TelemetryAnalyzer.Sample s(long ms,int cycle,boolean ok){return new TelemetryAnalyzer.Sample(ms,0,0,0,0,.5,.5,cycle,ok);}@Test void groupsCyclesAndSlicesTime(){var samples=List.of(s(0,1,true),s(20,1,true),s(40,2,false));var w=new TelemetryWindow();assertEquals(2,w.byCycle(samples).size());assertEquals(2,w.between(samples,10,40).size());}@Test void comparesRuns(){var a=new TelemetryAnalyzer().analyze(List.of(s(0,1,true)));var bad=new TelemetryAnalyzer().analyze(List.of(s(0,1,false)));assertEquals("regression",new RunComparator().compare(a,bad).verdict());}@Test void markdownIncludesFaults(){var r=new TelemetryAnalyzer().analyze(List.of(s(0,1,false)));assertTrue(new ReportFormatter().markdown(r).contains("auto-reliability"));}}
